import { test, expect } from '@playwright/test';

test.describe('Date Picker Keyboard Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/date-picker');
  });

  test('should allow full date picker operation using only keyboard navigation', async ({ page }) => {
    // Open date picker by pressing Enter on input field
    const dateInput = page.getByRole('textbox', { name: /date/i });
    await dateInput.press('Enter');

    // Verify calendar is visible
    const calendar = page.getByRole('region', { name: /calendar/i });
    await expect(calendar).toBeVisible();

    // Navigate to previous month using arrow keys
    const prevMonthBtn = page.getByRole('button', { name: /previous month/i });
    await prevMonthBtn.press('ArrowLeft');
    await expect(calendar).toBeVisible();

    // Navigate to next month using arrow keys
    const nextMonthBtn = page.getByRole('button', { name: /next month/i });
    await nextMonthBtn.press('ArrowRight');
    await expect(calendar).toBeVisible();

    // Navigate to next year using arrow keys
    const nextYearBtn = page.getByRole('button', { name: /next year/i });
    await nextYearBtn.press('ArrowRight');
    await expect(calendar).toBeVisible();

    // Navigate to next day using arrow keys
    const today = page.getByText(/today/i);
    await today.press('ArrowRight');
    await expect(calendar).toBeVisible();

    // Navigate to previous day using arrow keys
    const prevDay = page.getByText(/yesterday/i);
    await prevDay.press('ArrowLeft');
    await expect(calendar).toBeVisible();

    // Select a date using Enter key
    const targetDate = page.getByText('15');
    await targetDate.press('Enter');

    // Verify date is selected and input is updated
    await expect(dateInput).toHaveValue(/1[0-9]{2}\/\d{2}/);
    await expect(dateInput).toContainText('15');
  });

  test('should handle keyboard navigation when date picker is already open', async ({ page }) => {
    // Open date picker by pressing Enter on input field
    const dateInput = page.getByRole('textbox', { name: /date/i });
    await dateInput.press('Enter');

    // Verify calendar is visible
    const calendar = page.getByRole('region', { name: /calendar/i });
    await expect(calendar).toBeVisible();

    // Navigate to next month using arrow keys
    const nextMonthBtn = page.getByRole('button', { name: /next month/i });
    await nextMonthBtn.press('ArrowRight');
    await expect(calendar).toBeVisible();

    // Navigate to previous month using arrow keys
    await nextMonthBtn.press('ArrowLeft');
    await expect(calendar).toBeVisible();

    // Navigate to next year using arrow keys
    const nextYearBtn = page.getByRole('button', { name: /next year/i });
    await nextYearBtn.press('ArrowRight');
    await expect(calendar).toBeVisible();

    // Navigate to previous year using arrow keys
    await nextYearBtn.press('ArrowLeft');
    await expect(calendar).toBeVisible();

    // Select a date using Enter key
    const selectedDate = page.getByText('1');
    await selectedDate.press('Enter');

    // Verify date is selected and input is updated
    await expect(dateInput).toHaveValue(/01\/\d{2}\/\d{4}/);
    await expect(dateInput).toContainText('1');
  });
});
